  "args": {
    "name": "Rates Watch Data",
    "operation": "add",
    "widgets_json": {
      "rates_live_chart": {
        "name": "Rates Live Chart",
        "description": "TradingView chart for treasury futures.",
        "endpoint": "/rates-live-udf",
        "type": "advanced_charting",
        "w": 20,
        "h": 18,
        "category": "Macro",
        "staleTime": 900000,
