            "label": "Contract",
            "value": "ZN",
            "description": "Treasury futures contract."
          }
        ],
        "data": {
          "defaultSymbol": "ZN",
          "updateFrequency": 30000
        }
      },
      "yield_curve": {
        "name": "Yield Curve",
        "description": "Plotly treasury yield curve snapshot.",
        "endpoint": "/yield-curve",
        "type": "chart",
        "w": 20,
        "h": 9,
        "staleTime": 900000,
        "raw": true
      },
      "curve_spread_metric": {
        "name": "2s10s Spread",
        "description": "Current 2s10s spread in bps.",
        "endpoint": "/curve-spread",
        "type": "metric",
        "w": 6,
        "h": 4,
        "staleTime": 900000
      }
    },
    "apps_json": [
      {
        "name": "Rates Advanced Live",
        "description": "TradingView rates chart and curve.",
        "tabs": {
          "chart": {
            "id": "chart",
            "name": "Chart",
            "layout": [
              {
                "i": "rates_live_chart",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 18
              }
            ]
          },
          "curve": {
            "id": "curve",
